def tampil(kepala):
    hasil = []
    while kepala:
        hasil.append(kepala.data)
        kepala = kepala.berikut
    return hasil

def hapus(kepala, nilai):
    if kepala and kepala.data == nilai:
        return kepala.berikut
    s = kepala
    while s and s.berikut:
        if s.berikut.data == nilai:
            s.berikut = s.berikut.berikut   # lewati simpul yang dihapus
            break
        s = s.berikut
    return kepala

