def hitung_postfix(ekspresi):
    tumpukan = []
    for token in ekspresi.split():
        if token in '+-*/':
            b = tumpukan.pop()
            a = tumpukan.pop()
            if token == '+': tumpukan.append(a + b)
            elif token == '-': tumpukan.append(a - b)
            elif token == '*': tumpukan.append(a * b)
            else: tumpukan.append(a / b)
        else:
            tumpukan.append(int(token))
    return tumpukan.pop()

