class HashMap:
    def __init__(self):
        self.ember = [[] for _ in range(4)]
        self.n = 0
        self.rehash = 0

    def _indeks(self, kunci, banyak):
        h = 0
        for c in str(kunci):
            h = (h * 31 + ord(c)) % 2**32
        return h % banyak

    def put(self, kunci, nilai):
        e = self.ember[self._indeks(kunci, len(self.ember))]
        for p in e:
            if p[0] == kunci:
                p[1] = nilai
                return
        e.append([kunci, nilai])
        self.n += 1
        if self.n / len(self.ember) > 0.75:
            self._perbesar()

    def _perbesar(self):
        baru = [[] for _ in range(len(self.ember) * 2)]
        for e in self.ember:
            for kunci, nilai in e:
                baru[self._indeks(kunci, len(baru))].append([kunci, nilai])
        self.ember = baru
        self.rehash += 1

    def get(self, kunci):
        for k, v in self.ember[self._indeks(kunci, len(self.ember))]:
            if k == kunci:
                return v
        return None

