def quick_sort(a, tingkat=0):
    if len(a) <= 1:
        return a
    pivot = a[len(a) // 2]
    kecil = [x for x in a if x < pivot]
    sama = [x for x in a if x == pivot]
    besar = [x for x in a if x > pivot]
    print('  ' * tingkat + f'pivot {pivot}: {kecil} | {besar}')
    return quick_sort(kecil, tingkat + 1) + sama + quick_sort(besar, tingkat + 1)

