def dijkstra(g, awal):
    jarak = {awal: 0}
    pq = [(0, awal)]
    while pq:
        d, s = heapq.heappop(pq)
        if d > jarak[s]:
            continue
        for t, w in g[s].items():
            if d + w < jarak.get(t, float('inf')):
                jarak[t] = d + w
                heapq.heappush(pq, (d + w, t))
    return jarak

