from collections import deque

def urutkan(g):
    masuk = {s: 0 for s in g}
    for s in g:
        for t in g[s]:
            masuk[t] += 1
    q = deque(s for s in g if masuk[s] == 0)
    hasil = []
    while q:
        s = q.popleft()
        hasil.append(s)
        for t in g[s]:
            masuk[t] -= 1
            if masuk[t] == 0:
                q.append(t)
    if len(hasil) < len(g):
        return 'siklus pada: ' + ', '.join(sorted(s for s in g if masuk[s] > 0))
    return hasil

